/* Review-only Mac workflow. Synthetic data, no fetch, no device APIs, no persistence. */
'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mains=[['library','系统图库','photo'],['folders','文件夹','folder'],['backup','备份概览','shield'],['transfers','传输任务','transfer'],['receiver','接收设备','device'],['settings','设置','settings']];
const review=new URLSearchParams(location.search),entry=id=>catalog.find(x=>x.id===id);
let route=entry(review.get('screen'))?review.get('screen'):'backup',scenario='',tab=entry(route).owner,stack=[],feedback='',busy=false,formError='',draft={},scrolls=new Map();
const model={scopePhotos:true,scopeVideos:true,scopeLive:true,scopeAlbums:false,paired:true,paused:false,automatic:true,folderAutomatic:true,initial:true,layout:'平铺',folderSort:'修改时间 · 从新到旧',filter:'全部',kind:'全部',source:'全部',sort:'加入时间 · 从新到旧',selected:new Set(),selecting:false,force:false,treeOpen:true,name:'示例 Mac',appearance:'跟随系统',thumbnails:true,concurrency:'2',cacheBudget:'5 GB',reserve:'1 GB',reclaim:true,logDays:'14 天',logLimit:'5000',automaticUpdates:true,history:'未开始',page:1,queries:'',copied:false};
const button=(t,id,kind='',disabled=false)=>`<button class="button ${kind}" data-open="${id}" ${disabled?'disabled':''}>${esc(t)}</button>`;
const action=(t,a,kind='',disabled=false)=>`<button class="button ${kind}" data-do="${a}" ${busy||disabled?'disabled':''} ${t==='×'?'aria-label="关闭 / Close"':''}>${esc(t)}</button>`;
let preferenceRows=false;
const setting=(t,n='',id='',value='',symbol='')=>`<${id?'button':'div'} class="setting" ${id?`data-open="${id}"`:''}>${symbol&&!preferenceRows?icon(symbol):''}<div class="grow"><strong>${esc(t)}</strong>${n?`<p>${esc(n)}</p>`:''}</div>${value?`<span>${esc(value)}</span>`:''}${id?icon('chevron'):''}</${id?'button':'div'}>`;
const group=(t,body)=>`<section class="card ${/class="(?:setting|value-setting)"/.test(body)?'preference-group':''}">${t?`<h3>${esc(t)}</h3>`:''}${body}</section>`;
const note=(t,body='',tone='')=>`<div class="notice ${tone}">${icon(tone?'alert':'info')}<div class="grow"><strong>${esc(t)}</strong>${body?`<p>${esc(body)}</p>`:''}</div></div>`;
const toggle=(t,n,key)=>`<div class="setting"><div class="grow"><strong>${esc(t)}</strong><p>${esc(n)}</p></div><input type="checkbox" class="toolbar-checkbox" role="switch" aria-label="${esc(t)}" data-toggle="${key}" ${model[key]?'checked':''} ${busy?'disabled':''}></div>`;
const field=(t,key,value,type='text')=>`<label class="field">${esc(t)}<input data-edit="${key}" value="${esc(value)}" type="${type}" ${busy?'disabled':''}></label>`;
const textarea=(t,key,value,n)=>`<label class="field">${esc(t)}<small>${esc(n)}</small><textarea data-edit="${key}" ${busy?'disabled':''}>${esc(value)}</textarea></label>`;
const select=(t,key,values,current)=>`<label class="field">${esc(t)}<select data-edit="${key}" ${busy?'disabled':''}>${values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
const valueSelect=(title,key,values,current)=>`<label class="value-setting"><strong>${esc(title)}</strong><select aria-label="${esc(title)}" data-edit="${key}" ${busy?'disabled':''}>${values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
const choices=(values,key,current)=>`<div class="menu">${values.map(v=>`<button class="button" data-choice="${key}" data-value="${esc(v)}">${current===v?icon('check'):icon('circle')}${esc(v)}</button>`).join('')}</div>`;
const steps=()=>`<div class="steps"><div class="step"><b>1</b><div><strong>打开接收端</strong><p>在 Pixel 备份鸭中点“连接新设备”，选择连接 Mac。</p></div></div><div class="step"><b>2</b><div><strong>扫码配对</strong><p>用 Pixel 扫描此 Mac 显示的配对码。两台设备连接可互通的同一局域网。</p></div></div></div>`;
const cloud=()=>note('已保存与云端备份不同','备份鸭确认的是 Pixel 系统相册保存状态。Google 相册云端结果需单独核对。');
const fileStates={preparing:['等待准备原件','clock'],queued:['等待发送','clock'],running:['正在传输','transfer'],confirming:['等待接收端确认','clock'],received:['已接收 · 待处理','clock'],saved:['已保存到 Pixel 相册','check'],failed:['相册处理失败','alert']};
const files=Array.from({length:48},(_,i)=>({id:i,name:`IMG_${5442-i}.${i%5===0?'MOV':'HEIC'}`,type:i%5===0?'视频 · 00:18':i%3===0?'实况':'照片',time:i===2?'未提供':'2026/10/02 12:'+String(59-i).padStart(2,'0'),state:i<2?'failed':i<4?'running':i===4?'preparing':i<6?'confirming':i<8?'received':'saved',source:i%4===0?'相机 SD 卡':'系统图库'}));
function rows(list=files.slice(0,12),detail='transfer-detail'){return list.map(f=>`<button class="file" data-open="${detail}" data-file="${f.id}"><span class="thumb">${icon(f.type.includes('视频')?'play':'photo')}</span><span class="grow"><strong>${esc(f.name)}</strong><p>${esc(f.type)} · ${esc(f.time)} · ${esc(f.source)}</p></span><span class="pill ${f.state}">${icon(fileStates[f.state][1])}${fileStates[f.state][0]}</span></button>`).join('')}
function currentFile(){return files[model.currentFile||0]}
function failure(t='操作未完成，原设置与原件保留。'){return note('操作未完成',t,'error')+action('重试','retry','primary')}
const recovery=()=>note('操作计划已保存，需要恢复确认','恢复完成前此来源暂停发送。重启或重试会复用原计划的设备与范围；不会重新纳入后来新增文件。','error')+action('恢复未完成操作','recover-source','primary');
const defs=values=>`<dl class="definitions">${values.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;
function content(id){preferenceRows=['settings','backup','history-settings','about','cache','cache-reclaim','log-retention','concurrency','device-name','language','appearance'].includes(id);const failed=/失败|无效|失效|拒绝|不可用|无网络/.test(scenario);switch(id){
case 'library':return scenario==='权限未决定'||scenario==='权限拒绝'?`<div class="empty"><img src="../../assets/AppIcon.png" alt=""><h2>允许访问照片</h2><p>只读取你授权的照片与视频，原件不会修改。</p>${button(scenario==='权限拒绝'?'查看权限设置':'允许访问照片','system-photos','primary')}</div>`:scenario==='读取中'?note('正在读取系统图库…','使用静态占位，不闪烁、不改变网格槽位。'):scenario==='无照片'||scenario==='筛选为空'?`<div class="empty"><h2>${scenario==='无照片'?'还没有可读取的照片':'没有符合筛选的项目'}</h2><p>你的选择和已有备份记录会保留。</p>${button('选择其他类型','library-filter')}</div>`:`<div class="section-head"><div><p>${model.selecting?'已选 '+model.selected.size+' 项':'48 张照片与视频 · 示例数据'}</p></div><div class="actions">${button(model.kind,'library-filter')}${model.selecting?'':`<label class="grid-size">${icon('photo')}<input type="range" min="100" max="260" value="140" aria-label="缩略图大小"></label>`}${action(model.selecting?'完成':'选择','toggle-library-selection')}${model.selecting?button('备份所选','selected-backup','primary',model.selected.size===0):''}</div></div><div class="gallery">${files.slice(8,38).map(f=>`<button class="photo ${model.selected.has(f.id)?'selected':''}" data-library-item="${f.id}" aria-label="${model.selecting?'选择':'预览'} ${f.name}">${model.selecting?`<span class="selection">${model.selected.has(f.id)?icon('check'):''}</span>`:''}${f.type==='照片'?'':`<span>${esc(f.type)}</span>`}</button>`).join('')}</div>${cloud()}`;
case 'library-filter':return choices(['全部','照片','实况','视频','连拍'],'kind',model.kind);
case 'selected-backup':return `<h3>已选 ${model.selected.size||12} 个项目</h3>${toggle('重新发送已传输过的项目','开启后重新处理所选项目，在 Pixel 相册生成新副本；Google 相册仍可能去重。','force')}${note(model.force?'重新备份所选项目':'跳过已接收且未变化的内容',model.force?'Pixel 保留的相同且已校验原件可直接复用，不重复发送这些字节；云端结果单独核对。':'其余所选项目加入准备和传输队列。')}${scenario==='提交失败'?failure('项目尚未加入队列，保留当前选择，重试或取消。'):''}`;
case 'photo-detail':{const f=currentFile();return `<div class="preview"></div><h3>${esc(f.name)}</h3><div class="actions">${action('上一项','preview-prev')}${action('下一项','preview-next')}${action('照片信息','preview-info')}</div>${model.previewInfo?defs([['类型',scenario],['拍摄时间',f.time],['尺寸','4032 × 3024']]):''}${scenario.includes('不可用')&&!model.cloudPreview?note('允许从 iCloud 加载？','只加载预览，不创建备份任务。')+action('允许加载','preview-cloud'):''}`;}


case 'folders':return scenario==='空来源'?`<div class="empty"><img src="../../assets/AppIcon.png" alt=""><h2>添加第一个文件夹</h2><p>相机 SD 卡、电脑文件夹与外置硬盘都可作为来源。</p>${button('添加文件夹','system-folder','primary')}</div>`:`<div class="section-head"><div><h2>文件夹</h2><p>备份照片和视频，保留原文件。</p></div>${button('添加文件夹','system-folder','primary')}</div>${scenario==='全局暂停'?note('传输已暂停','来源自动备份设置未改变。恢复当前队列后继续。','warning'):''}${scenario==='读取失败'?failure('来源配置无法读取，请重试；不会清除已有配置。'):''}${['相机 SD 卡','Pictures'].map((t,i)=>group('',`<div class="row">${icon('folder')}<div class="grow"><h3>${t}</h3><p>${i?'~/Pictures':'/Volumes/Camera'}</p></div>${button('更多','folder-menu')}</div><div class="row">${note(scenario==='离线'&&i===0?'SD 卡未连接':scenario==='扫描中'?'正在扫描':'自动备份已开启','56 个文件 · 606.1 MB')}${i?button('2 个未备份项目','folder-issues'):''}</div><div class="section-head">${button('查看文件','folder-detail')}${action('备份现有文件','folder-backup')}${toggle('自动备份','','folderAutomatic')}</div>`)).join('')}`;
case 'folder-menu':return `<div class="menu">${action('重新扫描','folder-scan')}${button('备份规则','folder-rules')}${button('在 Finder 中显示','system-reveal')}${button('移除来源','folder-remove','danger')}</div>`;
case 'folder-add':return `<h3>相机 SD 卡</h3><p>/Volumes/Camera（演示）</p><p class="footnote">包含子文件夹中的照片与视频。</p> ${toggle('备份现有文件','关闭后只建立基线，不立即备份现有文件。','initial')}${toggle('自动备份','启用后新增和修改的内容自动加入队列。','folderAutomatic')}${setting('备份规则','','folder-rules')}${scenario==='规则展开'?rulesFields():''}${scenario==='来源重叠'?note('该路径与已有来源重叠','请更换路径，避免重复扫描同一批文件。','error'):scenario==='保存失败'?failure('添加未完成，保留当前输入。'):''}<p class="footnote">不修改原文件。关闭窗口后继续备份，退出应用后停止。</p>`;
case 'folder-rules':return (scenario==='保存失败'?recovery():'')+`<h3>相机 SD 卡</h3>${rulesFields()}${scenario==='高级语法'?note('规则语法','每行一条，相对来源根目录；大小写有区别。目录写作 Temp/**；黑名单优先。'):''}${note('保存后重新扫描','不改原文件、已排队任务或已接收记录。')}${failed?note('规则未能保存','仍保留原规则与当前输入，请检查表达式后重试。','error'):''}`;
case 'folder-remove':return (/失败/.test(scenario)?recovery():'')+ `<h3>从备份来源移除“相机 SD 卡”？</h3><p>停止扫描此来源，移除来源配置和本地索引。不会删除原文件或 Pixel 已接收的文件；已有队列独立保留。</p>${failed?failure():note('这是移除来源，不是删除照片。','','warning')}`;
case 'folder-help':return group('自动备份',setting('新增和修改','每个来源独立开启；建立基线后的已有文件不会冒充新增。'))+group('备份现有文件',setting('备份当前文件','备份点击时已有的照片和视频；已备份且未修改的文件会跳过。开启自动备份后，新增和修改的文件也会加入任务。'))+note('文件夹 → 更多 → 备份规则','说明为纯阅读，不会帮你启动备份或切换页面。');
case 'folder-detail':return `<div class="section-head"><div><h2>相机 SD 卡</h2><p>/Volumes/Camera · 56 个媒体文件</p></div>${button('备份规则','folder-rules')}</div><div class="section-head">${action('备份现有文件','folder-backup')}${toggle('自动备份','','folderAutomatic')}</div><div class="section-head">${button(model.folderSort,'folder-sort')}<div class="segmented">${['平铺','按文件夹'].map(t=>`<button class="${model.layout===t?'active':''}" data-layout="${t}">${t}</button>`).join('')}</div></div>${scenario==='加载中'?note('正在读取来源文件…'):scenario==='加载失败'?failure('保留展开目录、筛选与排序后重试。'):scenario==='离线'?note('SD 卡未连接','插回设备再扫描；此前备份记录保留。','warning'):scenario==='无文件'?note('没有符合规则的媒体文件。'):scenario==='等待配对'?note('先连接接收设备，再备份此来源。'):model.layout==='按文件夹'||scenario==='文件夹树'?`<div class="tree">${action((model.treeOpen?'▾':'▸')+' DCIM','tree')}${model.treeOpen?`<div class="tree"><h3>100CAMERA</h3>${rows(files.slice(8,14),'folder-file-detail')}</div>`:''}</div>`:rows(files.slice(8,20),'folder-file-detail')}${action('加载更多文件','more')}${note('列表时间按当前排序字段显示','未备份问题在该来源的问题详情里查看；发送或相册失败在传输任务查看。')}`;
case 'folder-sort':return choices(scenario==='目录排序'?['名称 · A–Z','名称 · Z–A']:['修改时间 · 从新到旧','修改时间 · 从旧到新','名称 · A–Z','名称 · Z–A','大小 · 从大到小','大小 · 从小到大'],'folderSort',model.folderSort);
case 'folder-file-detail':return `<h3>${esc(currentFile().name)}</h3>${defs([['相对路径',scenario==='路径很长'?'DCIM/'+('nested-folder/'.repeat(10))+currentFile().name:'DCIM/100CAMERA/'+currentFile().name],['文件时间',scenario==='时间缺失'?'未提供':'2026/10/02 12:59'],['大小','8.5 MB'],['来源','相机 SD 卡'],['状态',scenario]])}${note('文件夹时间来自原文件元数据','不将接收时间冒充拍摄时间。')}${button('在 Finder 中显示','system-reveal')}${button('查看传输任务','transfers')}`;
case 'folder-issues':return `<h2>未备份文件</h2><p>来源：相机 SD 卡。扫描和读取问题不等于 Pixel 相册处理失败。</p>${scenario==='无问题'?note('没有需要处理的来源问题。'):group('',setting('unreadable-original.jpg','原件暂时无法读取','folder-issue-detail','','alert')+setting('missing-motion.MOV','实况原件缺少必要资源','folder-issue-detail','','alert'))}${note('来源原文件保留','可重试读取、在 Finder 检查或忽略当前版本。')}`;
case 'folder-issue-detail':return (/失败/.test(scenario)?recovery():'')+ `<h3>unreadable-original.jpg</h3><p class="path">DCIM/${'long-directory/'.repeat(5)}unreadable-original.jpg</p>${note(scenario==='原因缺失'?'尚未记录具体原因':'媒体原件无法读取','这属于发送前准备问题，原文件没有删除。','warning')}${scenario==='已请求重试'?note('已请求重试','仅将该失败版本加入重试范围；全局暂停时继续等待。'):scenario==='重试失败'?failure('请求未提交，保留原问题。'):''}${button('在 Finder 中显示','system-reveal')}${button('忽略此版本','folder-ignore')}`;
case 'folder-ignore':return (/失败/.test(scenario)?note('忽略已生效，记录尚未保存','原件保留；可恢复未完成操作，不能把派生记录写入失败当作未忽略。','error')+action('恢复未完成操作','recover-source','primary'):'')+ `<h3>忽略这个文件版本？</h3><p>从问题列表移除当前失败，并在以后扫描中跳过此版本。原文件保留；文件修改产生新版本后可再次加入备份。</p>${failed?failure():note('忽略不会删除原件。','','warning')}`;
case 'backup':return scenario==='未配对'?`<div class="empty"><img src="../../assets/AppIcon.png" alt=""><h2>先连接你的 Pixel</h2><p>配对完成后，可按来源选择自动备份或备份现有文件。</p>${button('连接接收设备','receiver','primary')}</div>`:scenario==='加载中'?note('正在读取备份记录…'): `<div class="section-head"><div><h2>备份概览</h2><p>统计此接收设备的已有任务，不仅是今天的照片。</p></div></div><div class="hero">${group('',`<div class="row"><h3 class="grow">备份进度</h3><span class="pill">${esc(scenario==='已保存'?'传输完成':scenario)}</span></div><div class="metric">${scenario==='已保存'?120:91}<small>/ 120 个文件已保存到 Pixel 相册</small></div><div class="meter"><span style="width:${scenario==='已保存'?100:76}%"></span></div><p>${scenario==='已保存'?'全部已保存到 Pixel 相册':'27 个进行中 · 2 个需要处理'}</p><div class="actions">${action(model.paused?'继续传输':'暂停传输',model.paused?'resume':'pause','primary')}${button('传输任务','transfers')}</div>`)}${group('示例 Pixel',`<p>已配对 · 局域网连接</p><p>https://192.0.2.10:8484（演示）</p>${button('设备详情','receiver')}`)}</div><section class="content-section"><div class="section-head"><h3>备份设置</h3>${button('更多设置 ›','backup-settings')}</div>${group('',toggle('自动备份新增照片','','automatic')+setting('文件夹','相机 SD 卡 · Pictures · 2 个来源','folders'))}</section><section class="content-section"><div class="section-head"><h3>最近传输</h3>${button('全部','transfers')}</div>${rows(files.slice(0,3))}</section>`;
case 'transfers':{const matching=files.filter(f=>(model.filter==='全部'||model.filter==='需处理'&&f.state==='failed'||model.filter==='已保存'&&f.state==='saved'||model.filter==='进行中'&&['preparing','queued','running','confirming','received'].includes(f.state))&&(model.source==='全部'||f.source===model.source));return `<div class="section-head"><span>${matching.length} 项</span>${button('↕ '+model.sort,'transfer-sort')}${button('状态说明 ›','status-guide','link')}</div><div class="section-head"><div class="segmented">${['全部','进行中','需处理','已保存'].map(v=>`<button class="${model.filter===v?'active':''}" data-category="${v}">${v}</button>`).join('')}</div>${button(model.source,'transfer-source')}</div>${scenario==='读取失败'?failure('现有记录和筛选保留。'):scenario==='加载中'?note('正在读取传输记录…'):scenario==='无任务'||scenario==='筛选为空'?note('没有匹配的任务','更换筛选不会删除队列记录。'):rows(matching.slice((model.page-1)*12,model.page*12))}${action('加载更多任务','more')}`;}
case 'transfer-filter':return choices(['全部','进行中','需处理','已保存'],'filter',model.filter);
case 'transfer-source':return choices(['全部','系统图库','相机 SD 卡','Pictures'],'source',model.source);
case 'transfer-sort':return choices(['最新拍摄','最早拍摄','最近加入','最早加入'],'sort',model.sort);
case 'transfer-detail':{const f=currentFile(),received=['已接收待处理','已保存','相册失败'].includes(scenario);return `<h3>${esc(f.name)}</h3>${defs([['类型',f.type],['拍摄时间',scenario==='日期缺失'?'未提供':f.time],['来源',f.source],['接收设备','示例 Pixel（历史任务目标，演示）'],['大小','8.5 MB'],['状态',scenario]])}<ul class="timeline" data-role="transfer-detail"><li class="${received?'confirmed':'pending'}">${received?'原件已接收并校验':'原件传输'}<p>${received?'接收确认时间：10/02 13:03（演示）':'接收确认时间未记录'}</p></li><li class="${scenario==='已保存'?'confirmed':scenario==='相册失败'?'failed':'pending'}">${scenario==='已保存'?'已保存到 Pixel 相册':scenario==='相册失败'?'相册处理失败':'Pixel 相册状态待确认'}<p>相册保存时间未记录</p></li><li class="pending">Google 相册云端<p>云端状态未知，请在 Google 相册确认。</p></li></ul>${/失败/.test(scenario)?note('失败原因','原件与任务记录保留，具体原因以真实记录为准。','error'):''}${scenario==='请求失败'?failure('重试请求未能提交，仍保留失败状态。'):''}`;}

case 'status-guide':return group('',[["等待传输", "文件已准备好，正在等待空闲传输名额和接收端可用。"], ["等待系统调度", "已准备原件，尚未发送。"], ["正在传输", "只有字节真正传输且进度可用时画进度线。"], ["等待接收端确认", "发送完成后不画满进度槽。"], ["等待 Wi-Fi 或接收端恢复", "网络、空间或调度条件恢复后重试，原件与任务保留。"], ["等待自动重试", "网络、空间或调度条件恢复后重试，原件与任务保留。"], ["已暂停", "当前队列已暂停；来源自动备份设置不变，继续后恢复发送。"], ["等待加入手机相册", "原件已接收，正在等待 Pixel 相册处理；不代表云端上传。"], ["相册保存尚未确认", "有接收回执，但尚无相册结果；仍归进行中。"], ["手机相册处理失败，请在接收端重试", "原件保留在 Pixel，可在单项详情请求重新处理；请求成功不等于相册成功。"], ["已加入手机相册", "不代表 Google 相册云端已上传。"], ["需要处理", "传输或相册处理失败。打开文件查看原因和恢复方式。"]].map(([title,body])=>setting(title,body)).join(''));
case 'preparation':return `<h2>准备原件</h2><p>这些项目尚未成为字节传输任务，单独显示。</p>${note(scenario,scenario==='等待空间'?'先等待本机缓存或磁盘空间释放。':scenario==='来源不可用'?'原件尚未在本机，可能等待 iCloud 下载。':'准备状态不是云端备份结果。',/失败|不可用/.test(scenario)?'warning':'')}${scenario==='无项目'?'':rows(files.slice(3,9),'transfer-detail')}`;
case 'history-list':return `<h2>历史扫描记录</h2><p>已有图库扫描范围冻结；新加入资产由自动备份边界处理。</p>${note(scenario,scenario==='暂停'?'仅暂停扫描，不停止已排队传输。':'扫描和原件准备独立统计。')}${button('查看已有照片扫描设置','history-settings')}${scenario==='无记录'?'':rows(files.slice(10,16),'transfer-detail')}`;
case 'receiver':return scenario==='未配对'?`<h2>连接你的 Pixel</h2><p>两台设备连接可互通的同一局域网，配对一次即可。</p>${steps()}${button('显示 Mac 配对码','pair-code','primary')}${note('找不到接收端？','检查 Pixel 接收服务和 Wi‑Fi；VPN 应允许局域网连接。')}`:`<h2>示例 Pixel</h2><p>已配对 · 局域网连接</p><div class="hero">${group('连接状态',note(scenario,scenario==='连接不可用'?'配对仍保留；等待局域网连接恢复。':'设备名称和地址来自真实配对记录。')+button('查看连接状态','connection-status'))}${group('配对其他设备',`<p>不会自动清除历史任务。</p>${button('显示 Mac 配对码','pair-code','primary')}`)}</div>${defs([['网络地址','https://192.0.2.10:8484（演示）'],['远端温度',scenario==='连接不可用'?'未提供':'32.7 °C（演示）'],['远端可用空间',scenario==='连接不可用'?'未提供':'24 GB（演示）']])}`;
case 'pair-code':return `<p>在接收设备打开备份鸭，选择连接 Mac，再扫描下方二维码。两台设备连接可互通的同一局域网。</p>${scenario==='有效'?`<div class="qr-demo">${icon('qr')}<strong>演示，无效二维码</strong></div><p>真实码有有效期；过期后重新生成，不当作身份认证的替代。</p>`:scenario==='配对成功'?note('配对已完成（演示）','返回原接收设备页面，更新已配对身份。'):scenario==='生成中'||scenario==='配对中'?note(scenario+'…','取消会停止本次配对会话。'):note(scenario==='过期'?'配对码已过期':scenario==='没有网络'?'没有可用局域网地址':'配对码生成失败','保留此前配对，检查网络或重新生成。','error')}`;
case 'connection-status':return group('真实连接状态',setting(scenario,scenario==='无远端读数'?'发送端协议未提供远端温度、空间及云端结果。':scenario==='在线'?'当前可连接；不是全部文件完成证明。':'历史配对与已确认结果保留。'))+cloud();
case 'settings':return `<h2>设置</h2><div class="settings-grid"><div class="settings-column">${group('设备身份',setting('本机名称','','device-name',model.name))}${group('照片预览',toggle('允许从 iCloud 加载预览','不会开始备份。','cloudPreview'))}${group('本机存储',setting('本地缓存','','cache','1.8 GB / '+model.cacheBudget))}</div><div class="settings-column">${group('显示与语言',setting('外观','','appearance',model.appearance)+setting('语言','','language','中文')+setting('列表显示','','list-display'))}${group('诊断',setting('运行记录','','diagnostics')+setting('日志保留','','log-retention'))}</div></div>${group('帮助与关于',setting('使用帮助','','help')+setting('关于备份鸭','','about','0.3.0'))}`;
case 'list-display':return group('列表显示',toggle('显示缩略图','仅加载可见项，关闭可减少读取和解码。','thumbnails')+setting('文件列表','平铺或按文件夹展示。','folder-sort',model.layout));
case 'backup-settings':return group('备份范围',toggle('照片','','scopePhotos')+toggle('视频','','scopeVideos')+toggle('实况照片','','scopeLive')+toggle('限定相簿','','scopeAlbums')+(model.scopeAlbums?toggle('家庭相簿','','scopeFamily'):'')+note('选中的媒体类型 ∩ 相簿','改变范围不会自动开始历史备份。'))+group('系统图库',toggle('自动备份新增照片','开启后仅备份新增照片，已有范围独立控制。','automatic'))+group('传输设置',valueSelect('同时传输任务数','concurrency',['1','2','3','4'],model.concurrency))+group('已有照片',button('备份已有照片','history-settings'))+group('文件夹',setting('文件夹来源','','folders'));
case 'about':return `<h2>关于备份鸭</h2>${group('',setting('应用版本','','','0.3.0 (46)'))}<section class="content-section"><div class="section-head"><h3>应用更新</h3></div>${group('',toggle('自动检查更新','','automaticUpdates'))}<p class="footnote">更新由系统窗口提供，检查失败保留当前版本与数据。</p>${button('检查更新','system-update','primary')}</section>${button('官方网站','system-website')}`;
case 'history-settings':return toggle('新增照片自动备份','只影响启用后的新增，历史范围单独开始。','automatic')+ `<h3>已有照片扫描</h3>${note(scenario,scenario==='快照失效'?'本次扫描快照不可用，重建范围前请确认。':scenario==='已暂停'?'扫描暂停，已加入队列的任务继续传输。':'每次扫描冻结可访问的已有资产范围。')}${defs([['已检查','120（演示）'],['待准备','27（演示）']])}${scenario==='快照失效'?action('重新建立扫描范围','history-restart'):action(scenario==='扫描中'?'暂停扫描':scenario==='已暂停'?'继续扫描':'开始扫描',scenario==='扫描中'?'history-pause':scenario==='已暂停'?'history-resume':'history-start','primary')}${failed?failure('扫描操作未完成，已有队列和设置保留。'):''}`;
case 'concurrency':return valueSelect('同时传输任务数','concurrency',['1','2','3','4'],draft.concurrency??model.concurrency)+note('同时发送文件数量','较高并发可能增加本机内存、网络和 Pixel 接收压力。保存失败保留原值。');
case 'cache':return group('准备缓存',setting('临时文件已占用','','',scenario==='缓存为空'?'0 KB':'1.8 GB')+valueSelect('缓存最多占用','cacheBudget',['1 GB','2 GB','5 GB','10 GB','20 GB','50 GB'],draft.cacheBudget??model.cacheBudget))+`<p class="footnote">达到上限时会暂停准备原件，缓存空间恢复后继续。</p>`+group('保留空间',setting('这台设备剩余空间','','',scenario==='空间不足'?'800 MB':'22 GB')+valueSelect('设备至少保留','reserve',['1 GB','2 GB','5 GB','10 GB'],draft.reserve??model.reserve))+`<p class="footnote">低于保留空间时暂停准备原件，不会删除其他文件。</p>`+group('缓存回收',toggle('传输完成后自动回收','','reclaim')+setting('检查并回收缓存','','cache-reclaim'))+`<p class="footnote">只回收接收端已确认的缓存副本；原件保留，云端结果单独确认。</p>`+(failed?failure('本机配置未更新，请重试。'):'');
case 'cache-reclaim':return note(scenario,scenario==='已释放'?'已释放 1.6 GB，不删除来源照片、Pixel 相册或配对。':scenario==='部分保留'?'不满足安全条件的原件会继续保留；协议只报告释放字节，不返回保留数量。':scenario==='没有可释放项'?'没有当前可安全回收的临时文件。':'检查应用内中转副本；结果不代表 Google 相册云端已完成。',failed?'error':'');
case 'diagnostics':return `<div class="section-head"><div><h2>运行记录</h2><p>错误码、阶段、计数和时间；不显示私人照片。</p></div>${button('导出诊断报告','diagnostics-export')}</div><div class="section-head">${button('日志保留','log-retention')}${action('显示最新记录','refresh')}</div>${failed?failure('已有诊断记录保留。'):group('',setting('准备原件被暂停','2026/10/02 13:03 · local_cache_budget','log-detail')+setting('接收端不可达','2026/10/02 13:04 · receiver_unavailable','log-detail')+setting('记录已保存','2026/10/02 13:05 · publication_saved','log-detail'))}${cloud()}`;
case 'log-detail':return `<h3>receiver_unavailable</h3>${defs([['时间',scenario==='缺少时间'?'未记录':'2026/10/02 13:04（演示）'],['阶段','连接检查'],['任务数量','27'],['原因','receiver_unavailable']])}${scenario==='长上下文'?note('上下文','合成测试说明 '.repeat(30)):note('记录不包含照片内容或配对凭据。')}`;
case 'log-retention':return valueSelect('日志保留时间','logDays',['1 天','7 天','14 天','30 天','90 天'],draft.logDays??model.logDays)+valueSelect('最大日志条目','logLimit',['1000','5000','10000','20000'],draft.logLimit??model.logLimit)+note('只影响日志','不清除照片、队列、接收记录或设备配对。');
case 'diagnostics-export':return note(scenario==='导出成功'?'报告文件已准备就绪':scenario==='导出中'?'正在生成诊断报告…':scenario==='已取消'?'已返回应用，未确认外部保存结果':'准备诊断报告',scenario==='导出成功'?'这只证明私有临时JSON已生成。下一步打开系统分享，保存到外部目的地的结果不由此确认。':'报告不包含照片内容、文件名、完整路径或配对凭据。',failed?'error':'')+(scenario==='导出失败'?action('重新生成报告','prepare-report','primary'):scenario==='导出成功'?button('打开系统分享 / 保存','system-save','primary'):scenario==='导出中'?'':action('准备报告文件','prepare-report','primary'));
case 'device-name':return field('设备名称','name',draft.name??model.name)+note('设备身份不会改变','修改名称保留配对和备份记录，名称最多 40 个可显示字符。')+(scenario==='名称无效'?note('名称无效','不能为空或包含控制字符，最多 40 个字符。','error'):failed?failure('原名称保留。'):'');
case 'appearance':return choices(['跟随系统','浅色','深色'],'appearance',model.appearance)+note('应用内外观','主窗口、设置窗口及弹层使用同一偏好；材质跟随辅助功能回退。');
case 'language':return note('跟随系统对该应用的语言设置','系统设置 → 通用 → 语言与地区；为备份鸭选择语言并重新打开应用。')+(failed?failure('请从苹果菜单手动进入系统设置。'):button('打开系统设置','system-language','primary'));
case 'updates':return group('当前版本',setting('备份鸭','0.2.0（演示，真实值来自应用）')+toggle('自动检查更新','使用 Sparkle 正常更新渠道。','automaticUpdates'))+note(scenario,scenario==='退出后安装'?'等待原件准备结束，暂停发送，更新后按原状态恢复。':scenario==='检查失败'?'检查网络后再试，不删除原件或应用数据。':'更新过程由 Sparkle 原生窗口提供。',failed?'error':'')+button('检查更新','system-update','primary');
case 'help':return `<h2>使用帮助</h2>${group('',[['help-connection','连接与配对'],['help-library','图库备份'],['help-folders','文件夹与规则'],['help-background','后台与暂停'],['help-results','接收、保存与云端'],['help-recovery','失败恢复与诊断'],['help-permissions','权限与空间']].map(([id,t])=>setting(t,'',id)).join(''))}`;
case 'help-connection':return group('配对方向',setting('Mac 显示码，Pixel 扫描','操作路径：接收设备 → 显示 Mac 配对码。二维码有效期来自真实协议。'))+group('网络与 VPN',setting('同一局域网','两台设备需要能直接互通。VPN 请允许局域网流量。'))+note('这里不自动生成配对码','看完后返回接收设备页面操作。');
case 'help-library':return group('新增与已有',setting('自动备份新增照片','从启用时建立图库边界；导入旧拍摄日期的新增资产仍按新增识别。')+setting('备份已有照片','独立扫描冻结范围，扫描过程中新增资产不混入已有范围。')+setting('手动备份所选','默认跳过已接收且未变化项目；强制重传选项只影响所选项目。'));
case 'help-folders':return group('每个来源独立',setting('现有文件与自动备份','添加时选择备份现有文件；自动备份负责以后新增和修改。')+setting('规则','白名单为空包含所有支持媒体；黑名单优先，保存后重新扫描。')+setting('移除来源','不会删除原文件或 Pixel 接收记录。'));
case 'help-background':return group('保持应用运行',setting('关闭窗口不退出应用','菜单栏继续显示状态；退出备份鸭或 Mac 睡眠会停止后台工作。')+setting('暂停传输','即时控制当前队列，不改变来源自动备份设置。')+setting('历史扫描暂停','只暂停扫描，不停止已排队发送。'));
case 'help-results':return group('三个事实',setting('已接收','原件在接收端持久保存并校验。')+setting('已保存到 Pixel 相册','经过相册发布确认，才显示此状态。')+setting('Google 相册云端','需在 Google 相册核对，备份鸭不能用本地状态证明云端成功。'));
case 'help-recovery':return group('恢复路径',setting('发送失败','操作路径：传输任务 → 失败 → 单项详情 → 重试。')+setting('相册失败','原件保留；处理重试请求不代表已经成功。')+setting('导出诊断','操作路径：设置 → 诊断 → 导出诊断报告。')+setting('应用更新','操作路径：设置 → 帮助与关于 → 检查更新。'))+note('帮助不跳转到操作流程','看完说明后回到原页面，手动选择对应功能。');
case 'help-permissions':return group('本机访问',setting('照片权限','只有你允许的系统图库项目可扫描、预览和备份。')+setting('文件夹权限','使用系统选择器建立只读访问；拔出设备或撤销权限不会当作照片失败。')+setting('缓存空间','达到预算或剩余空间不足，暂停准备更多原件；空间恢复后继续。'));
case 'menu-bar':return `<div class="menu"><img src="../../assets/BackupDuckMonochrome.svg" alt="备份鸭菜单栏单色图标" width="20" height="20">${note('状态：'+scenario)}${button('打开备份鸭','backup')}${action(model.paused?'继续传输':'暂停传输',model.paused?'resume':'pause')}${button('设置','settings')}${button('关于备份鸭','about')}${action('退出备份鸭（演示）','quit')}</div>`;
case 'system-folder':case 'system-photos':case 'system-save':case 'system-language':case 'system-update':case 'system-reveal':case 'system-website':return `<div class="boundary"><h2>${esc(entry(id).title)}</h2><p>这是系统 / 外部边界说明，不仿造真实系统控件，不申请权限，不打开设备、网站或真实文件。</p>${note('模拟状态：'+scenario,{ 'system-folder':'生产应用使用 NSOpenPanel，选择可访问目录后进入添加确认；取消返回原页面。','system-photos':'生产使用 PhotoKit 权限；允许后读取，拒绝时保留权限说明。','system-save':'生产在私有报告准备成功后打开系统分享/保存UI；返回不生成目的地已写入的应用内成功结论。','system-language':'打开系统设置，用户自行为应用设置语言；失败留在原页面提示。','system-update':'生产使用 Sparkle 检查、下载、签名验证与安装，不跳过校验。','system-reveal':'使用 Finder 定位来源文件；路径不可访问时保留错误。','system-website':'仅通过明确链接打开备份鸭官方网站。' }[id])}${action('模拟返回应用','system-return')}${id==='system-folder'?action('模拟选择目录','folder-picked','primary'):id==='system-save'?action('模拟结束系统分享','report-location','primary'):''}</div>`;
default:throw Error('Missing Mac design screen '+id);
}}
function rulesFields(){return `<p>选择哪些照片和视频参与备份。不需要筛选时，两个输入框都留空。</p>${textarea('只备份这些（白名单）','include',draft.include??'**/*.{jpg,JPG}','每行一条相对路径；符合任意一条即纳入，留空包含所有支持媒体。')}${textarea('跳过这些（黑名单）','exclude',draft.exclude??'Temp/**','符合任意一条即排除，黑名单优先；例如 Temp/** 跳过整个目录。')}${note('规则不能增加不支持的媒体格式。')}`}
function footer(id){switch(id){
case 'selected-backup':return action('取消','back')+action(busy?'正在加入…':'备份所选','confirm-selection','primary');
case 'folder-add':return action('取消','back')+action(busy?'正在添加…':'添加文件夹','save','primary',!model.initial&&!model.folderAutomatic);
case 'folder-rules':return action(scenario==='保存失败'?'完成':'取消','back')+action(scenario==='保存失败'?'恢复未完成操作':busy?'保存中…':'保存并重新扫描',scenario==='保存失败'?'recover-source':'save','primary');
case 'folder-remove':return action(scenario==='失败'?'完成':'取消','back')+action(scenario==='失败'?'恢复未完成操作':'移除来源',scenario==='失败'?'recover-source':'remove-source','danger');
case 'folder-ignore':return action(scenario==='失败'?'完成':'取消','back')+action(scenario==='失败'?'恢复未完成操作':'忽略此版本',scenario==='失败'?'recover-source':'ignore-version','danger');
case 'folder-issue-detail':return action('关闭','back')+action(busy?'请求中…':'重试读取原件','retry-file','primary');
case 'transfer-detail':return action('关闭','back')+(/失败|请求失败|重试中/.test(scenario)?action(busy?'请求中…':'重试任务','retry-file','primary'):'');
case 'pair-code':return action('取消配对','back')+(/过期|网络|失败/.test(scenario)?action('重新生成配对码','regenerate','primary'):scenario==='有效'?action('模拟配对成功','paired','primary'):'');
case 'device-name':return action('取消','back')+action(busy?'保存中…':'保存','save','primary');
case 'diagnostics-export':return action('关闭','back');
default:return action('关闭','back');
}}
function activity(){const t={手动暂停:['传输已暂停','点击继续恢复，已接收原件保留'],高温暂停:['Pixel 正在降温','等待接收端解除温度保护，不推测温度读数'],相册处理失败:['2 个文件未保存到相册','原件保留，可在任务详情请求重试'],已保存:['传输完成','Google 相册云端请单独核对'],等待连接:['等待 Pixel 重新连接','保留队列，局域网连接恢复后继续发送'],等待相册处理:['已接收 · 等待相册处理','字节传输结束，Pixel 正在处理'],未配对:['等待连接接收设备','配对完成后选择来源开始备份']}[scenario]||['准备和发送原件','状态来自当前队列，示例数据'];return `<div class="activity">${icon(/失败/.test(scenario)?'alert':'transfer')}<div class="grow"><strong>${t[0]}</strong><p>${t[1]}</p></div>${button('传输任务','transfers','link')}${scenario==='正在传输'?'<div class="progress"></div>':''}</div>`}
function frame(id){const item=entry(id),owner=item.owner,main=mains.some(x=>x[0]===id);return `<div class="app-frame"><aside class="app-side"><div class="brand"><img src="../../assets/AppIcon.png" alt="">备份鸭</div><nav class="side-links" aria-label="应用导航">${mains.map(([i,t,s],n)=>`${n===0?'<small>来源</small>':n===2?'<small>备份任务</small>':n===4?'<small>管理</small>':''}<button data-tab="${i}" class="${owner===i?'active':''}">${icon(s)}${t}</button>`).join('')}</nav><div class="side-status">${icon(model.paired?'wifi':'link')} ${model.paired?'已连接（演示）':'未配对'}<br>示例 Pixel</div></aside><div class="workspace"><header class="toolbar">${main?'':action('返回','back','link')}<h1>${esc(item.title)}</h1>${id==='library'?button('类型与筛选','library-filter'):id==='folders'?button('文件夹说明','folder-help'):''}${button('菜单栏','menu-bar','link')}</header><main class="content" data-screen="${id}">${content(id)}</main>${['settings','receiver'].includes(owner)?'':activity()}</div></div>`}
function render(){const spec=entry(route);if(!scenario)scenario=spec.states[0];const position=$('.content')?.scrollTop;if(position!==undefined)scrolls.set(route,position);$('#scenario').innerHTML=spec.states.map(x=>`<option ${x===scenario?'selected':''}>${esc(x)}</option>`).join('');let markup;if(['sheet','confirm','popover'].includes(spec.kind)){let under=stack.slice().reverse().find(x=>entry(x.route).kind==='page')?.route||spec.owner;const original=scenario;scenario=entry(under).states[0];markup=frame(under);scenario=original;markup+=`<div class="overlay"><section class="dialog ${spec.kind==='confirm'?'confirm':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><h2 id="dialog-title">${esc(spec.title)}</h2>${action('×','back','icon')}</header><div class="dialog-body" data-screen="${route}">${formError?note('操作未完成',formError,'error'):''}${content(route)}</div>${feedback?`<div class="feedback in-dialog" role="status">${esc(feedback)}</div>`:''}<footer class="dialog-foot">${footer(route)}</footer></section></div>`}else markup=frame(route)+(feedback?`<div class="feedback" role="status">${esc(feedback)}</div>`:'');$('#app').innerHTML=markup;const ordinary=$('.app-frame');if(['sheet','confirm','popover'].includes(spec.kind))ordinary.inert=true;$('.content')?.scrollTo(0,scrolls.get(route)||0);$('#screen-picker').innerHTML=catalog.map(x=>`<option value="${x.id}" ${route===x.id?'selected':''}>${esc(x.title)} · ${x.kind}</option>`).join('');$('#catalog').innerHTML=catalog.filter(x=>(x.title+x.id).includes($('#search').value)).map(x=>`<button data-open="${x.id}" class="${x.id===route?'selected':''}">${esc(x.title)}<small>${x.kind} · ${x.states.length} 状态</small></button>`).join('');$('#contract').innerHTML=`<div class="contract"><strong>${esc(spec.id)} · ${esc(spec.title)}</strong><p>真实入口：${esc(spec.source)} / ${esc(spec.symbol)}<br>展示方式：${esc(spec.kind)} · 所属工作流：${esc(spec.owner)}<br>状态：${esc(spec.states.join(' / '))}<br>原生进度：${esc(spec.native)}</p><p>模拟显示不证明原生已实现、业务成功或云端上传。系统边界由真实系统UI实现。</p></div>`;document.documentElement.dataset.screen=route;if(['sheet','confirm','popover'].includes(spec.kind))queueMicrotask(()=>{$('.dialog button')?.focus();scheduleReviewFocus()});}
function open(id){if(!entry(id))throw Error('Unknown Mac route '+id);stack.push({route,scenario,tab,scroll:$('.content')?.scrollTop||0});route=id;tab=entry(id).owner;scenario=entry(id).states[0];busy=false;formError='';feedback='';draft={name:model.name,concurrency:model.concurrency,cacheBudget:model.cacheBudget,reserve:model.reserve,logDays:model.logDays,logLimit:model.logLimit,include:'**/*.{jpg,JPG}',exclude:'Temp/**'};render()}
function back(){if(busy)return;const prev=stack.pop();if(prev){route=prev.route;scenario=prev.scenario;tab=prev.tab;scrolls.set(route,prev.scroll)}else{route=tab;scenario=entry(tab).states[0]}formError='';feedback='';render()}
function save(){const id=route;if(id==='device-name'&&(!draft.name.trim()||[...draft.name.trim()].length>40||/[\x00-\x1f]/.test(draft.name))){formError='请输入 1–40 个可显示字符，不能包含控制字符。';scenario='名称无效';render();return}if(['folder-rules','folder-add'].includes(id)&&((draft.include||'').includes('[')|| (draft.exclude||'').includes('['))){formError='演示规则校验失败，原规则和输入保留。';scenario='规则无效';render();return}const shouldFail=/失败|重叠/.test(scenario);busy=true;feedback='正在保存…';render();setTimeout(()=>{if(route!==id)return;busy=false;if(shouldFail){feedback='';formError='保存未完成，原设置与输入保留，请重试。';render();return}for(const key of ['name','concurrency','cacheBudget','reserve','logDays','logLimit'])if(key in draft)model[key]=draft[key];back();feedback='设置已保存（演示）。';render()},450)}
function perform(a){switch(a){
case 'back':back();return;
case 'preview-play':feedback='本机媒体播放由原生PhotosUI/AVKit提供；此处仅示意。';render();return;
case 'toggle-library-selection':model.selecting=!model.selecting;if(!model.selecting)model.selected.clear();render();return;
case 'save':save();return;
case 'pause':model.paused=true;scenario='手动暂停';feedback='当前传输已暂停（演示），自动备份设置不变。';break;
case 'resume':model.paused=false;scenario='正在传输';feedback='已请求继续传输（演示）。';break;
case 'confirm-selection':if(scenario==='提交失败'){formError='请求未能提交，照片选择保留。';break}feedback=model.force?'已请求重新处理并在 Pixel 相册创建副本，Google 相册仍可能去重（演示）。':'未备份所选项目已加入队列（演示）。';model.selected.clear();route='backup';tab='backup';scenario='等待发送';stack=[];break;
case 'folder-picked':back();open('folder-add');return;
case 'folder-backup':feedback='备份现有文件请求已提交；未变化且已接收内容会跳过（演示）。';break;
case 'expand-add-rules':scenario='规则展开';feedback='';break;
case 'folder-scan':feedback='已请求重新扫描来源（演示），不强制重复上传。';break;
case 'remove-source':case 'ignore-version':if(/失败/.test(scenario)){formError='请求未完成，来源与原件保留。';break}back();feedback=a==='remove-source'?'来源已移除，原文件与接收记录保留（演示）。':'当前版本已忽略，原件保留（演示）。';break;
case 'tree':model.treeOpen=!model.treeOpen;break;
case 'more':model.page=Math.min(4,model.page+1);feedback='已加载下一批示例记录，选择和排序保留。';break;
case 'refresh':feedback='记录已刷新（演示），筛选和滚动位置保留。';break;
case 'retry-file':if(/失败|请求失败/.test(scenario)){formError='重试请求暂未提交，原件及失败状态保留。';break}scenario=entry(route).states.includes('已请求重试')?'已请求重试':scenario;feedback='仅提交重试请求，成功前仍保留失败状态（演示）。';break;
case 'recover-source':formError='';feedback='原计划的确认记录已恢复（演示）；原设备与冻结范围保持，后续仍由真实任务确认。';scenario=entry(route).states[0];break;
case 'retry':formError='';scenario=entry(route).states[0];feedback='已回到可重试状态（演示）。';break;
case 'regenerate':scenario='生成中';render();setTimeout(()=>{if(route==='pair-code'){scenario='有效';render()}},450);return;
case 'paired':model.paired=true;back();route='receiver';tab='receiver';scenario='连接正常';feedback='已更新配对信息（演示），历史结果保留。';break;
case 'history-start':case 'history-resume':model.history='扫描中';scenario='扫描中';feedback='已有范围扫描已开始（演示）。';break;
case 'history-pause':model.history='已暂停';scenario='已暂停';feedback='仅暂停扫描，已排队传输继续。';break;
case 'history-restart':scenario='扫描中';feedback='已重新建立已有范围（演示）。';break;
case 'prepare-report':scenario='导出中';busy=true;render();setTimeout(()=>{if(route==='diagnostics-export'){busy=false;scenario='导出成功';feedback='私有报告文件已准备，可打开系统分享；目的地保存尚未确认。';render()}},450);return;
case 'report-location':back();feedback='已返回应用；这里只确认报告文件准备就绪，不确认外部目的地保存。';break;
case 'system-return':back();return;
case 'quit':feedback='演示：退出备份鸭会停止后台执行；没有退出真实应用。';break;
default:throw Error('Unknown Mac action '+a);
}render()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled||busy)return;if(b.dataset.file!==undefined)model.currentFile=Number(b.dataset.file);if(b.dataset.category){model.filter=b.dataset.category;render();return}if(b.dataset.open){open(b.dataset.open);return}if(b.dataset.tab){stack=[];route=tab=b.dataset.tab;scenario=entry(route).states[0];feedback='';render();return}if(b.dataset.select!==undefined){const id=Number(b.dataset.select);model.selected.has(id)?model.selected.delete(id):model.selected.add(id);render();return}if(b.dataset.choice){model[b.dataset.choice]=b.dataset.value;if(b.dataset.choice==='appearance'&&b.dataset.value!=='跟随系统')document.documentElement.dataset.theme=b.dataset.value==='深色'?'dark':'light';back();return}if(b.dataset.layout){model.layout=b.dataset.layout;render();return}if(b.dataset.do)perform(b.dataset.do)});
document.addEventListener('input',e=>{if(e.target.dataset.edit){draft[e.target.dataset.edit]=e.target.value;if(['cache','concurrency','log-retention','backup-settings'].includes(route)){const key=e.target.dataset.edit;if(!/失败/.test(scenario)){model[key]=e.target.value;feedback='设置已保存。'}else{draft[key]=model[key];feedback='保存未完成，原值保留。'}render()}}if(e.target.id==='search')render()});
document.addEventListener('change',e=>{if(e.target.dataset.toggle){model[e.target.dataset.toggle]=e.target.checked;render()}});
function updateReviewWidth(){const viewport=$('#viewport');if(viewport&&viewport.clientWidth)$('#desktop').style.setProperty('--review-width',viewport.clientWidth+'px')}
function scheduleReviewFocus(){updateReviewWidth();const raf=typeof requestAnimationFrame==='function'?requestAnimationFrame:fn=>queueMicrotask(fn);raf(()=>raf(()=>focusReviewDialog()))}
function focusReviewDialog(){const viewport=$('#viewport'),dialog=$('.dialog');if(!viewport||!dialog)return;updateReviewWidth();if(typeof dialog.getBoundingClientRect!=='function')return;const target=viewport.scrollLeft+dialog.getBoundingClientRect().left-viewport.getBoundingClientRect().left-12;viewport.scrollTo({left:Math.max(0,target),behavior:'instant'})}
$('#focus-dialog').onclick=()=>{if($('.dialog'))scheduleReviewFocus();else $('#viewport').scrollTo({left:210,behavior:'instant'})};
$('#screen-picker').onchange=e=>open(e.target.value);
$('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';$('#theme').textContent=document.documentElement.dataset.theme==='dark'?'切换浅色':'切换深色'};
$('#width').onchange=e=>{const n=Number(e.target.value);$('#desktop').style.width=n+'px';$('#desktop').style.height=(n===900?620:n===960?740:800)+'px';scheduleReviewFocus()};
$('#font').onchange=e=>{$('#desktop').style.setProperty('--font',e.target.value);$('#desktop').dataset.large=Number(e.target.value)>1.2};
if(typeof ResizeObserver==='function')new ResizeObserver(()=>scheduleReviewFocus()).observe($('#viewport'));
$('#motion').onchange=e=>$('#desktop').classList.toggle('reduced',e.target.checked);
$('#scenario').onchange=e=>{scenario=e.target.value;formError='';feedback='';busy=/保存中|提交中|重试中/.test(scenario);model.paused=scenario==='手动暂停';render()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!busy){back();return}if(e.key!=='Tab')return;const d=$('.dialog');if(!d)return;const controls=[...d.querySelectorAll('button,input,textarea,select')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0]?.focus()}});
window.reviewAPI={open:id=>open(id),setScenario:value=>{if(!entry(route).states.includes(value))throw Error('Unknown state '+value);scenario=value;busy=false;formError='';feedback='';render()},catalog,content,footer,model,inspect:()=>({route,scenario,tab,stack:stack.length})};
render();

document.addEventListener('click',e=>{const b=e.target.closest('[data-library-item]');if(!b)return;const id=+b.dataset.libraryItem;if(model.selecting){model.selected.has(id)?model.selected.delete(id):model.selected.add(id);render()}else{model.currentFile=id;open('photo-detail')}});

document.addEventListener('click',e=>{const a=e.target.closest('[data-do]')?.dataset.do;if(a==='preview-info')model.previewInfo=!model.previewInfo;else if(a==='preview-cloud')model.cloudPreview=true;else if(a==='preview-prev')model.currentFile=Math.max(0,model.currentFile-1);else if(a==='preview-next')model.currentFile=Math.min(files.length-1,model.currentFile+1);else return;render()});

// Shared calendar-view reference; synthetic dates, never user metadata.
const renderBeforeTimeline = render;
render = function () {
  renderBeforeTimeline();
  const gallery = document.querySelector('.gallery');
  if (!gallery?.insertAdjacentHTML) return;
  const mode = model.viewMode || 'all';
  gallery.dataset.timeline = mode;
  const controls = document.createElement('div'); controls.className = 'actions timeline-controls';
  controls.innerHTML = [['all','全部 / All'],['days','日 / Days'],['months','月 / Months']].map(([value,label])=>`<button class="button" data-view-mode="${value}" aria-pressed="${mode===value}">${label}</button>`).join('');
  gallery.before(controls);
  if (mode !== 'all') Array.from(gallery.querySelectorAll('.photo')).forEach((photo,i)=>{
    if (i % 9 === 0) { const title = document.createElement('h3'); title.className='timeline-heading';title.textContent=mode==='months'?`2026 · ${10-Math.floor(i/9)}`:`2026 · 10 · ${12-Math.floor(i/9)}`;photo.before(title) }
  });
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-view-mode]');if(!b)return;model.viewMode=b.dataset.viewMode;render()});
render();
